data class SendInput(val conversationId:String,val text:String)
sealed interface SendResult { data class Accepted(val clientId:String):SendResult; data class Rejected(val reason:String):SendResult }
class SendMessageUseCase(private val repo:ChatRepository, private val ids:IdGenerator){
 suspend operator fun invoke(input:SendInput):SendResult {
  val text=input.text.trim()
  if(text.isEmpty()) return SendResult.Rejected("empty_message")
  val clientId=ids.next()
  repo.persistPending(input.conversationId,clientId,text)
  repo.enqueueSend(clientId)
  return SendResult.Accepted(clientId)
 }
}

class ObserveConversationUseCase(private val repo:ChatRepository){
 operator fun invoke(id:String):Flow<List<Message>> = repo.observeMessages(id)
}
